// Regenerates src/content/imageSizes.ts from the images in /public.
// Run after adding images: node scripts/image-sizes.mjs
import { imageSize } from "image-size";
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const lines = [
  "// generated by scripts/image-sizes.mjs, re-run after adding images",
  "export const imageSizes: Record<string, { w: number; h: number }> = {",
];
for (const dir of ["work", "life", "thoughts", "experience"]) {
  for (const file of readdirSync(join(root, "public", dir)).sort()) {
    const { width, height } = imageSize(readFileSync(join(root, "public", dir, file)));
    lines.push(`  "/${dir}/${file}": { w: ${width}, h: ${height} },`);
  }
}
lines.push("};", "");
writeFileSync(join(root, "src/content/imageSizes.ts"), lines.join("\n"));
